const seniorTopics={"daily": ["or-adrc", "or-cil-abilitree", "or-cil-eocil", "or-cil-eocil-the-dalles", "or-cil-hasl", "or-cil-ilr", "or-cil-lila", "or-cil-spokes", "or-cil-uvdn"], "accessibility": ["or-adrc", "or-cil-abilitree", "or-cil-eocil", "or-cil-eocil-the-dalles", "or-cil-hasl", "or-cil-ilr", "or-cil-lila", "or-cil-spokes", "or-cil-uvdn"], "vision": ["or-adrc"], "hearing": ["or-adrc"], "memory": ["alz-dementia-support", "or-adrc"], "costs": ["or-ship", "or-adrc", "or-legal-programs"], "rights": ["or-ombudsman", "or-legal-programs"]};
const ohioLiving=DATA.filter(x=>x.resource_role==='independent_living').map(x=>x.program_id),ohioCaregivers=DATA.filter(x=>x.resource_role==='caregiver_support').map(x=>x.program_id);
const ohioCenters=DATA.filter(x=>x.resource_role==='senior_center').map(x=>x.program_id);
const ohioHome=DATA.filter(x=>x.resource_role==='home_support').map(x=>x.program_id);
seniorTopics.daily.push(...ohioCenters);routes.local.push(...ohioCenters);
